import java.util.Scanner;

public class IncomeTax {
    private String name;
    private char gender;
    private double taxableIncome;
    private double tax;

    public IncomeTax() {
        name = "";
        gender = 'M';
        taxableIncome = 0.0;
        tax = 0.0;
    }

    public void accept() {
        Scanner in = new Scanner(System.in);
        System.out.print("Enter Taxpayer Name: ");
        name = in.nextLine();
        System.out.print("Enter Gender ('M'/'F'): ");
        gender = in.next().toUpperCase().charAt(0);
        System.out.print("Enter Annual Taxable Income (Rs): ");
        taxableIncome = in.nextDouble();
    }

    public void compute() {
        if (taxableIncome <= 250000.0) {
            tax = 0.0;
        } else if (taxableIncome <= 500000.0) {
            tax = (taxableIncome - 250000.0) * 0.05;
        } else if (taxableIncome <= 1000000.0) {
            tax = 12500.0 + (taxableIncome - 500000.0) * 0.20;
        } else {
            tax = 112500.0 + (taxableIncome - 1000000.0) * 0.30;
        }

        if (gender == 'F' && tax > 0) {
            tax -= (0.03 * tax); // 3% rebate for women
        }
    }

    public void display() {
        System.out.println("\n=========== INCOME TAX SLIP ===========");
        System.out.println("Taxpayer Name     : " + name);
        System.out.println("Gender            : " + gender);
        System.out.println("Taxable Income    : Rs. " + taxableIncome);
        System.out.println("Net Tax Payable   : Rs. " + tax);
        System.out.println("========================================");
    }

    public static void main(String[] args) {
        IncomeTax it = new IncomeTax();
        it.accept();
        it.compute();
        it.display();
    }
}
```

