import java.util.Scanner;

public class TemperatureBubbleSort {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        final int DAYS = 7;
        double[] temp = new double[DAYS];

        System.out.println("Enter temperatures for 7 days (in Celsius):");
        for (int i = 0; i < DAYS; i++) {
            System.out.print("Day " + (i + 1) + ": ");
            temp[i] = sc.nextDouble();
        }

        System.out.print("\nTemperatures before sorting: ");
        for (double t : temp) System.out.printf("%.1f C  ", t);
        System.out.println();

        for (int i = 0; i < DAYS - 1; i++) {
            for (int j = 0; j < DAYS - 1 - i; j++) {
                if (temp[j] < temp[j + 1]) { // Descending
                    double t = temp[j];
                    temp[j] = temp[j + 1];
                    temp[j + 1] = t;
                }
            }
        }

        System.out.print("Temperatures after sorting (Descending): ");
        for (double t : temp) System.out.printf("%.1f C  ", t);
        System.out.println();
    }
}
```

