import java.util.Scanner;

public class AutomorphicTrimorphicCheck {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        System.out.print("Enter a positive integer: ");
        long n = sc.nextLong();

        if (n <= 0) {
            System.out.println("Please enter a positive integer.");
            return;
        }

        long temp = n;
        long mod = 1;
        while (temp > 0) {
            mod *= 10;
            temp /= 10;
        }

        long square = n * n;
        long cube = n * n * n;

        boolean isAuto = (square % mod == n);
        boolean isTri = (cube % mod == n);

        System.out.println("\nNumber = " + n);
        System.out.println("Square = " + square + " (Ends with: " + (square % mod) + ")");
        System.out.println("Cube   = " + cube + " (Ends with: " + (cube % mod) + ")");

        if (isAuto) {
            System.out.println(n + " is an AUTOMORPHIC NUMBER.");
        } else if (isTri) {
            System.out.println(n + " is a TRIMORPHIC NUMBER.");
        } else {
            System.out.println(n + " is NEITHER Automorphic nor Trimorphic.");
        }
    }
}
```

