import java.util.Scanner;

public class MatrixVerticalMirror {
    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        System.out.print("Enter rows M: ");
        int m = in.nextInt();
        System.out.print("Enter cols N: ");
        int n = in.nextInt();

        int[][] mat = new int[m][n];
        int[][] mirror = new int[m][n];

        System.out.println("Enter matrix elements:");
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                mat[i][j] = in.nextInt();
                mirror[i][n - 1 - j] = mat[i][j]; // Reflect
            }
        }

        System.out.println("\nOriginal Matrix:");
        printMat(mat);

        System.out.println("\nMirror Matrix (Vertical Reflection):");
        printMat(mirror);
    }

    private static void printMat(int[][] a) {
        for (int[] row : a) {
            for (int v : row) System.out.printf("%5d", v);
            System.out.println();
        }
    }
}
```

