public class OverloadSeries {
    public void series(int n) {
        long sum = 0;
        for (int i = 1; i <= n; i++) {
            sum += (long) i * i;
        }
        System.out.println("Sum of squares (n = " + n + "): S = " + sum);
    }

    public void series(double a, int n) {
        double sum = 0.0;
        for (int i = 1; i <= n; i++) {
            sum += Math.pow(a, i) / i;
        }
        System.out.printf("Sum of a^i / i (a = %.1f, n = %d): S = %.4f\n", a, n, sum);
    }

    public static void main(String[] args) {
        OverloadSeries os = new OverloadSeries();
        os.series(10);
        os.series(2.0, 5);
    }
}
```

